def calculate_sum_set_size(T):
    N = len(T)
    sums = set()
    # S = {t_i + t_j | 0 <= i <= j <= N-1}
    for i in range(N):
        for j in range(i, N):
            sums.add(T[i] + T[j])
    return len(sums)

